module benchmark/solution

import std/fs (readFile, writeFile)
import std/string (split, trim, stringToInt, contains)
import std/list (map, filter, length)
import std/json (encode, jo, ja, kv, js, jint, Json)

type User = {name: string, age: int, email: string}

pure func parseRow(line: string) -> Option[User] =
  match split(trim(line), ",") {
    [name, ageStr, email] => match stringToInt(trim(ageStr)) {
      Some(age) => if age > 0 && contains(email, "@") then Some({name: trim(name), age: age, email: trim(email)}) else None,
      None => None
    },
    _ => None
  }

pure func parseRows(lines: [string]) -> [User] =
  match lines {
    [] => [],
    l :: rest => match parseRow(l) {
      Some(u) => u :: parseRows(rest),
      None => parseRows(rest)
    }
  }

pure func userToJson(u: User) -> Json =
  jo([kv("name", js(u.name)), kv("age", jint(u.age)), kv("email", js(u.email))])

export func main() -> () ! {IO, FS} {
  writeFile("users.csv", "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n");
  let content = readFile("users.csv");
  let lines = filter(\l. trim(l) != "", split(content, "\n"));
  let rows = match lines {
    [] => [],
    _ :: data => data
  };
  let users = parseRows(rows);
  writeFile("users.json", encode(ja(map(userToJson, users))));
  println("Converted ${show(length(users))} valid rows to users.json")
}

